// Regenerates lib/checkpoints/assets.generated.ts from the brand assets in public/.
// Run after replacing the logo SVG or the Logik font:
//   node scripts/generate-checkpoint-assets.mjs
import fs from "node:fs";

const font = fs.readFileSync("public/Font/Logik-ExtendedBoldOblique.ttf");
const logo = fs.readFileSync("public/PR_primarylogo.svg", "utf8");

const out =
  "// AUTO-GENERATED by scripts/generate-checkpoint-assets.mjs — do not edit by hand.\n" +
  "// Embeds the brand font + logo so QR sign generation needs no runtime file reads\n" +
  "// (serverless bundles do not include public/ on the filesystem).\n\n" +
  "export const LOGIK_FONT_BASE64 =\n  " +
  JSON.stringify(font.toString("base64")) +
  ";\n\n" +
  "export const PR_LOGO_SVG = " +
  JSON.stringify(logo) +
  ";\n";

fs.writeFileSync("lib/checkpoints/assets.generated.ts", out);
console.log(`Embedded font (${font.length} bytes) and logo (${logo.length} chars).`);
